jsonb_build_object('number',7,'question',E'다음 빈칸에 들어갈 말로 가장 적절한 것을 고르시오.\n\nYou will get a good grade __________ you do your best.','type','mcq','options',jsonb_build_array(E'if',E'as',E'before',E'because',E'although'),'answer',E'1','explanation',E'조건절 if'),
