jsonb_build_object('number',61,'question',E'다음 문장과 의미가 같은 것을 고르시오.\n\nIf you don''t start now, you will be late.\n\n① If you start now, you will be late.\n② Unless you start now, you will be late.\n③ Unless you start now, you won''t be late.\n④ If you start now, you won''t be late.\n⑤ Although you start now, you will be late.','type','mcq','options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),'answer',E'2','explanation',E'If ~ not = Unless, 시작하지 않으면 늦을 것'),
jsonb_build_object('number',62,'question',E'다음 문장과 의미가 같은 것을 고르시오.\n\nUnless she buys the tickets, she won''t go to the concert.\n\n① If she buys the tickets, she won''t go to the concert.\n② If she doesn''t buy the tickets, she will go to the concert.\n③ If she doesn''t buy the tickets, she won''t go to the concert.\n④ Unless she doesn''t buy the tickets, she won''t go to the concert.\n⑤ If she buys the tickets, she will go to the concert.','type','mcq','options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),'answer',E'3','explanation',E'Unless = If ~ not, 티켓을 사지 않으면 콘서트에 안 갈 것'),
jsonb_build_object('number',63,'question',E'다음 문장과 의미가 같은 것을 고르시오.\n\nTake the subway, and you''ll get there faster.\n\n① Unless you take the subway, you''ll get there faster.\n② If you take the subway, you''ll get there faster.\n③ If you will take the subway, you''ll get there faster.\n④ If you don''t take the subway, you''ll get there faster.\n⑤ Although you take the subway, you''ll get there faster.','type','mcq','options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),'answer',E'2','explanation',E'명령문 + and = If ~, 지하철을 타면 더 빨리 도착할 것'),
jsonb_build_object('number',64,'question',E'다음 문장과 의미가 같은 것을 고르시오.\n\nStudy hard, or you will fail the exam.\n\n① If you study hard, you will fail the exam.\n② Unless you study hard, you won''t fail the exam.\n③ If you don''t study hard, you will fail the exam.\n④ Unless you study hard, you will pass the exam.\n⑤ If you study hard, you won''t pass the exam.','type','mcq','options',jsonb_build_array(E'①',E'②',E'③',E'④',E'⑤'),'answer',E'3','explanation',E'명령문 + or = If ~ not, 열심히 공부하지 않으면 시험에 떨어질 것'),
